/* @autogenerated */
export interface AvatarSpec {
  initials: string; // "IC"
  hue: number; // tono OKLCH por hash, 0..359
  bg: string; // color-mix() del --mat-sys-primary-container del tema con el tono del hash
  fg: string; // ídem con --mat-sys-on-primary-container: contraste ≥ 4,5:1 en claro y oscuro
  ariaLabel: string; // "Icono de Luisitos"
}

/** Peso del color del tema en la mezcla: tiñe el avatar sin perder la variedad del hash. */
export const AVATAR_THEME_WEIGHT = 30;

/**
 * Tonos fijos (L y C de OKLCH) que se mezclan con el tema. Fondo claro sobre texto oscuro en modo claro y al revés en
 * oscuro, con una distancia de L suficiente para AA con cualquier tono (verificado en avatar-text.service.spec.ts).
 */
export const AVATAR_TONES = {
  light: { bg: [0.92, 0.06], fg: [0.36, 0.1] },
  dark: { bg: [0.36, 0.08], fg: [0.92, 0.04] },
} as const;

export function computeAvatarSpec(
  text: string,
  opts?: {
    maxLetters?: number; // por defecto 2
    hueRange?: [number, number]; // por defecto [0, 360)
    locale?: string; // por defecto, el del navegador
  },
): AvatarSpec {
  const { maxLetters = 2, hueRange = [0, 360], locale } = opts || {};

  const safe = (text ?? '').trim();
  const initials = getInitials(safe, maxLetters, locale) || '•';

  // Hash determinista del texto -> número
  const hash = stringHash(safe || 'fallback');
  // Mapear hash a un tono (H) dentro del rango indicado
  const hue = hueRange[0] + (Math.abs(hash) % (hueRange[1] - hueRange[0]));

  return {
    initials,
    hue,
    bg: themed('--mat-sys-primary-container', AVATAR_TONES.light.bg, AVATAR_TONES.dark.bg, hue),
    fg: themed('--mat-sys-on-primary-container', AVATAR_TONES.light.fg, AVATAR_TONES.dark.fg, hue),
    ariaLabel: safe ? `Icono de ${safe}` : 'Icono',
  };
}

function themed(token: string, light: readonly number[], dark: readonly number[], hue: number): string {
  const tone = ([l, c]: readonly number[]) => `oklch(${l} ${c} ${hue})`;
  return `color-mix(in oklch, var(${token}) ${AVATAR_THEME_WEIGHT}%, light-dark(${tone(light)}, ${tone(dark)}))`;
}

function getInitials(text: string, maxLetters: number, locale: string | undefined): string {
  if (!text) return '';
  // Normalizar, quitar espacios múltiples y signos raros al inicio/fin
  const cleaned = text
    .normalize('NFKD')
    .replace(/\p{Diacritic}/gu, '') // quitar acentos
    .replace(/\s+/g, ' ')
    .trim();

  // Si contiene email, usa la parte antes de @
  const base = cleaned.includes('@') ? cleaned.split('@')[0] : cleaned;

  // Dividir por espacios y guiones
  const parts = base.split(/[\s\-_.]+/).filter(Boolean);

  // Si es una sola palabra, toma primeras letras de la misma palabra
  if (parts.length === 1) {
    const word = parts[0];
    // toma letras significativas (letras y números)
    const letters = Array.from(word).filter((ch) => /\p{L}|\p{N}/u.test(ch));
    return letters.slice(0, maxLetters).join('').toUpperCase();
  }

  // Si hay varias palabras, toma la primera letra de las primeras N palabras significativas
  const stopwords = new Set(['de', 'del', 'la', 'las', 'el', 'los', 'the', 'of', 'da', 'do', 'dos', 'das', 'y']);
  const sig = parts
    .filter((w) => !stopwords.has(w.toLowerCase()))
    .slice(0, Math.max(maxLetters, 2)) // normalmente 2
    .map((w) => w[0])
    .join('')
    .toUpperCase();

  return sig.slice(0, maxLetters);
}

function stringHash(s: string): number {
  // Hash simple y rápido, determinista
  let h = 2166136261 >>> 0; // FNV-like
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h | 0;
}
